from fastapi import APIRouter, HTTPException
from pydantic import BaseModel
from rubik_solver import utils as rubik_utils

router = APIRouter(prefix="/solver", tags=["Solver"])

# The rubik-solver library uses these color letters:
# w=white, o=orange, g=green, r=red, b=blue, y=yellow
# Face order for the 54-char string: Top, Left, Front, Right, Back, Bottom

# Stage names for the Beginner method — the library solves these internally
# but returns one flat move list. We label stages by splitting on "Y" moves
# (Y = whole cube rotation = the library uses it as a stage separator)

STAGE_NAMES = [
    "White Cross",
    "White Corners",
    "Middle Layer Edges",
    "Yellow Cross",
    "Yellow Edges",
    "Yellow Corner Positions",
    "Yellow Corner Orientation",
]

STAGE_EXPLANATIONS = [
    "Form a white cross on the top face. Each white edge must align with its matching side center color.",
    "Insert the white corner pieces to fully complete the white (top) layer.",
    "Insert the middle layer edges using the Left or Right insertion algorithm.",
    "Form a yellow cross on the top face using: F R U R' U' F'",
    "Align the yellow edges so they match their side center colors.",
    "Move the yellow corners to their correct positions without twisting them.",
    "Twist the yellow corners in place to finish the cube. Repeat R' D' R D until each corner is oriented.",
]


class SolveRequest(BaseModel):
    cube_string: str   # 54 chars, colors: w o g r b y, faces: Top Left Front Right Back Bottom
    method: str = "Beginner"   # "Beginner" or "CFOP"


